begin;

with input as (
  select * from jsonb_to_recordset($catalog$[{"code":"IPAD-102-GEN789","display_name":"iPad 10.2-inch (Gen 7/8/9)","source_category":"iPad 10.2 Inch","notes":"Confirm that every case in this category fits all Gen 7, 8 and 9 devices.","review_status":"proposed"},{"code":"IPAD-10-GEN10","display_name":"iPad 10th Gen 10.9-inch","source_category":"iPad 10th Gen 10.9 Inch","notes":"Confirm whether any newer iPad model can use these cases.","review_status":"proposed"},{"code":"IPAD-97-LEGACY","display_name":"iPad 9.7-inch (Gen 5/6 and Air 1/2)","source_category":"iPad 9.7 Inch","notes":"Owner confirmed iPad Gen 5, Gen 6, Air 1 and Air 2.","review_status":"approved"},{"code":"IPAD-AIR11-2024","display_name":"iPad Air 11-inch (2024)","source_category":"iPad Air 11-inch 2024(Air 6","notes":"Confirm which older Air/Pro models, if any, can use this newer case.","review_status":"proposed"},{"code":"IPAD-AIR13-2024","display_name":"iPad Air 13-inch (2024)","source_category":"iPad Air 13-inch 2024 (Air 6)","notes":"Confirm whether the 2025/2026 Air 13-inch uses the same case.","review_status":"proposed"},{"code":"IPAD-AIR45-PRO11","display_name":"iPad Air 4/5 and iPad Pro 11 (2018-2022)","source_category":"iPad Air 4/5, Pro 11","notes":"Owner confirmed Air 4/5 and iPad Pro 11-inch models from 2018, 2020, 2021 and 2022.","review_status":"approved"},{"code":"IPAD-109-PRO11-LEGACY","display_name":"iPad Air 4/5 and iPad Pro 11 (2018-2022)","source_category":"iPad 10.9 inch/Pro 11","notes":"Owner confirmed Air 4/5 and iPad Pro 11-inch models from 2018, 2020, 2021 and 2022.","review_status":"approved"},{"code":"IPAD-MINI45","display_name":"iPad mini 4/5","source_category":"iPad mini 4/5","notes":"Confirm both mini 4 and mini 5 use every case in this profile.","review_status":"proposed"},{"code":"IPAD-MINI6","display_name":"iPad mini 6","source_category":"iPad mini 6","notes":"Confirm whether mini 7/A17 Pro is also supported by these cases.","review_status":"proposed"},{"code":"IPAD-PRO11-2024","display_name":"iPad Pro 11-inch (2024)","source_category":"iPad Pro 11-inch 2024","notes":"Confirm which older Pro 11 models, if any, can use this newer case.","review_status":"proposed"},{"code":"IPAD-129-LEGACY","display_name":"iPad Pro 12.9-inch (2018-2022)","source_category":"iPad 12.9 inch","notes":"Owner confirmed the 2018, 2020, 2021 and 2022 iPad Pro 12.9-inch models.","review_status":"approved"},{"code":"IPAD-PRO13-2024","display_name":"iPad Pro 13-inch (2024)","source_category":"iPad Pro 13-inch 2024","notes":"Confirm that older 12.9-inch cases are not assumed compatible in the reverse direction.","review_status":"proposed"},{"code":"SAMSUNG-A11-PLUS","display_name":"Samsung Galaxy Tab A11 Plus","source_category":"Samsung Tablet","notes":"Confirm exact Samsung model number and year; similar names can have different body dimensions.","review_status":"proposed"},{"code":"SAMSUNG-A7","display_name":"Samsung Galaxy Tab A7","source_category":"Samsung Tablet","notes":"Confirm exact Samsung model number and year; similar names can have different body dimensions.","review_status":"proposed"},{"code":"SAMSUNG-A8","display_name":"Samsung Galaxy Tab A8","source_category":"Samsung Tablet","notes":"Confirm exact Samsung model number and year; similar names can have different body dimensions.","review_status":"proposed"},{"code":"SAMSUNG-A9-PLUS","display_name":"Samsung Galaxy Tab A9 Plus","source_category":"Samsung Tablet","notes":"Confirm exact Samsung model number and year; similar names can have different body dimensions.","review_status":"proposed"},{"code":"SAMSUNG-S10","display_name":"Samsung Galaxy Tab S10","source_category":"Samsung Tablet","notes":"Confirm exact Samsung model number and year; similar names can have different body dimensions.","review_status":"proposed"},{"code":"SAMSUNG-S10-PLUS","display_name":"Samsung Galaxy Tab S10 Plus","source_category":"Samsung Tablet","notes":"Confirm exact Samsung model number and year; similar names can have