:"Universal 10-inch tablet fit","source_category":"Universal case","notes":"Confirm minimum and maximum device dimensions; size alone is not an exact compatibility promise.","review_status":"proposed"},{"code":"UNIVERSAL-7","display_name":"Universal 7-inch tablet fit","source_category":"Universal case","notes":"Confirm minimum and maximum device dimensions; size alone is not an exact compatibility promise.","review_status":"proposed"},{"code":"UNIVERSAL-8","display_name":"Universal 8-inch tablet fit","source_category":"Universal case","notes":"Confirm minimum and maximum device dimensions; size alone is not an exact compatibility promise.","review_status":"proposed"}]$catalog$::jsonb) as x(
    code text,
    display_name text,
    source_category text,
    notes text,
    review_status text
  )
)
insert into public.product_fit_profiles (code, display_name, source_category, notes, review_status)
select code, display_name, source_category, notes, review_status
from input
on conflict (code) do update
set display_name = excluded.display_name,
    source_category = excluded.source_category,
    notes = excluded.notes,
    review_status = case
      when product_fit_profiles.review_status = 'approved' then product_fit_profiles.review_status
      else excluded.review_status
    end,
    updated_at = timezone('utc'::text, now());

commit;
